# Each new question has an independent answer key, rationale and a traceable slide group.
# Cases are illustrations of the slide concept, never a claim the original slide listed this case.
extra=[]
def add(m,q,opts,right,reason,source,d=2):
    assert len(opts)==4 and 0<=right<4,(q,opts)
    extra.append(dict(module=m,q=q,options=opts,correct=right,explain=reason,source=source,difficulty=d,kind='aplicação didática'))
B='Big Data'; L='Raciocínio Lógico'; A='Inteligência Artificial'; C='Coleta de Dados'; S='Ciência de Dados'; I='Business Intelligence'; E='Ética e Confiança'
