# BIG DATA: varying stakes, cases, comparing Vs
add(B,'Uma empresa possui 4 PB de registros históricos, mas faz poucas consultas diárias. Qual V é mais evidente?',['Valor','Variedade','Volume','Velocidade'],2,'O destaque é a quantidade acumulada de dados, independentemente da frequência das consultas.',Bsrc,1)
add(B,'Uma bolsa de valores recebe alterações em milissegundos e exige reação imediata. Qual V domina?',['Velocidade','Veracidade','Volume','Valor'],0,'A ênfase está na rapidez com que dados chegam e precisam ser processados.',Bsrc,1)
add(B,'Um sistema reúne contratos em PDF, fotos, logs em JSON e tabelas SQL. Qual característica foi destacada?',['Veracidade','Volume','Valor','Variedade'],3,'Diversidade de fontes, estruturas e formatos descreve variedade.',Bsrc,1)
add(B,'Uma clínica descobre que parte dos cadastros contém datas de nascimento impossíveis. O problema é de…',['Variedade','Veracidade','Velocidade','Volume'],1,'A presença de erros e inconsistências reduz a confiabilidade dos dados.',Bsrc,1)
add(B,'A rede varejista cruza dados de venda para prever ruptura de estoque e reduzir perdas. O benefício exemplifica…',['Valor','Velocidade','Variedade','Volume'],0,'Valor expressa utilidade prática e melhores decisões extraídas dos dados.',Bsrc,1)
add(B,'Uma rede recebe mensagens, áudios e vídeos em tempo real. Qual par de Vs é diretamente mostrado?',['Veracidade e valor','Variedade e velocidade','Volume e veracidade','Valor e volume'],1,'Há diferentes formatos e rapidez na entrada dos eventos; volume não foi quantificado.',Bsrc,2)
add(B,'Qual afirmação é a mais precisa sobre Big Data segundo o slide?',['Exige exatamente 1 TB de informação','Sempre envolve inteligência artificial','Lida com conjuntos muito grandes ou complexos para tratamento tradicional','Significa qualquer banco relacional'],2,'O PDF aponta a escala/complexidade que desafia ferramentas tradicionais, sem um limite universal de tamanho.',Bsrc,1)
add(B,'Um e-commerce armazena bilhões de cliques. Só essa informação NÃO comprova qual dimensão?',['Volume','Acúmulo de registros','Grandeza do conjunto','Valor de negócio'],3,'Existir muito dado não implica que ele gere alguma utilidade de negócio.',Bsrc,2)
add(B,'Um app processa apenas 500 dados por segundo, mas cada registro precisa ser analisado em 5 ms. O foco é…',['Velocidade','Variedade','Veracidade','Volume'],0,'A exigência temporal de processamento caracteriza velocidade, mesmo sem enorme quantidade.',Bsrc,2)
add(B,'A presença de milhões de arquivos idênticos afeta principalmente qual V?',['Variedade','Veracidade','Volume','Valor'],2,'A quantidade pode ser grande sem diversidade de tipos de arquivo.',Bsrc,2)
add(B,'Qual par apresenta corretamente conceito e pergunta orientadora?',['Valor — quais formatos?','Variedade — quais formatos?','Volume — são confiáveis?','Veracidade — quanto tempo?'],1,'Variedade se refere à diversidade de formatos, fontes e estruturas.',Bsrc,1)
add(B,'Se dados foram coletados muito rapidamente, mas 40% são duplicados, temos dois aspectos:',['Velocidade alta e veracidade comprometida','Variedade alta e valor garantido','Valor alto e volume nulo','Veracidade alta e velocidade nula'],0,'Rapidez de geração e qualidade/confiabilidade são dimensões diferentes.',Bsrc,2)
add(B,'O mesmo dado é útil para personalização, mas foi coletado com erro. Que dois Vs entram em tensão?',['Volume e variedade','Velocidade e volume','Valor e veracidade','Variedade e velocidade'],2,'Utilidade (valor) e confiança na informação (veracidade) não são a mesma propriedade.',Bsrc,3)
add(B,'Milhões de vídeos de um único tipo de arquivo são destaque sobretudo para…',['Volume','Variedade','Veracidade','Valor'],0,'Muitos arquivos do mesmo formato indicam quantidade; não necessariamente diversidade.',Bsrc,2)
add(B,'A equipe garante que os registros foram validados, mas ainda não decidiu o que fazer com eles. Qual V foi tratado primeiro?',['Valor','Veracidade','Variedade','Velocidade'],1,'Validação de precisão e confiabilidade corresponde à veracidade.',Bsrc,2)
add(B,'Qual é uma interpretação equivocada dos Vs?',['Eles podem coexistir numa situação','Eles ajudam a descrever desafios','Uma aplicação pode destacar Vs diferentes','Todo sistema apresenta obrigatoriamente os cinco Vs no mesmo grau'],3,'As intensidades e desafios variam; o uso dos cinco conceitos não implica uniformidade.',Bsrc,3)
add(B,'Um serviço transforma dados de localização em previsão de chegada útil para o cliente. A decisão central revela…',['Volume','Variedade','Valor','Veracidade'],2,'A utilidade produzida a partir dos dados é a característica central do exemplo.',Bsrc,2)
add(B,'Um sistema tem arquivos de vídeo, texto e sensor, porém nenhum deles é confiável. É correto afirmar que…',['Variedade e veracidade podem ser avaliadas separadamente','Variedade garante veracidade','Mais formatos significam mais valor','A qualidade independe totalmente da análise'],0,'Ter formatos diversos não prova que o conteúdo seja confiável.',Bsrc,2)
add(B,'A plataforma enfrenta gargalo porque eventos chegam mais rápido do que consegue processar. Qual é o principal desafio?',['Valor','Velocidade','Variedade','Veracidade'],1,'A taxa de entrada supera a capacidade de tratamento em tempo útil.',Bsrc,3)
add(B,'Qual exemplo demonstra melhor veracidade, e não valor?',['A campanha aumentou as vendas','Os sensores enviam dados a cada segundo','O conjunto mistura áudio e fotos','A empresa remove duplicidades e corrige campos inválidos'],3,'Correção de inconsistências melhora a precisão e confiabilidade.',Bsrc,2)
add(B,'Uma equipe trocou tabelas em SQL por eventos JSON e imagens, mas o número total de registros não mudou. O que cresceu?',['Variedade','Volume necessariamente','Valor necessariamente','Veracidade necessariamente'],0,'A diversidade de formatos aumentou, não havendo evidência de aumento nas outras dimensões.',Bsrc,2)
add(B,'Uma empresa tem só dados de vendas atualizados diariamente, mas extrai ganhos expressivos com eles. O que se pode concluir?',['Há necessariamente alta velocidade','O valor pode existir sem grande variedade','O volume cresce sempre','Veracidade deixa de ser importante'],1,'Utilidade de negócio não exige obrigatoriamente alta diversidade de formatos.',Bsrc,3)
add(B,'O slide da Aula 1 enumera explicitamente quantos Vs?',['Três','Quatro','Cinco','Seis'],2,'A p. 9 registra cinco: velocidade, volume, variedade, veracidade e valor.', 'Aula 1 · p. 9',1)
add(B,'Segundo o PDF, o suposto sexto V possui qual definição obrigatória?',['Variabilidade','Visualização','Viscosidade','O PDF não especifica um sexto V'],3,'O slide apresenta cinco Vs. Não atribua uma sexta definição ao material sem evidência.', 'Aula 1 · p. 9',3)
add(B,'Qual escolha explica corretamente por que 5 Vs não são uma fórmula matemática?',['São perspectivas para caracterizar dados, não unidades de medida padronizadas','Representam as cinco fases obrigatórias do BI','São bancos de dados distintos','São cinco linguagens de programação'],0,'Os Vs descrevem dimensões conceituais e são úteis para interpretar cenários.',Bsrc,2)
add(B,'Uma cooperativa cruza documentos diferentes e consegue detectar fraudes. Qual leitura é adequada?',['Só existe variedade','Existem variedade e valor no cenário','Só existe veracidade','Não existe Big Data sem IA'],1,'Fontes heterogêneas sugerem variedade e detectar fraude sugere valor.',Bsrc,3)
add(B,'Qual exemplo enfatiza velocidade sem apontar necessariamente grande volume?',['Arquivo histórico de 10 TB','Mil fotos em formatos diferentes','Um sensor gera um único alerta que exige reação em 30 ms','Uma planilha de preços conferida por auditor'],2,'Uma exigência temporal rigorosa caracteriza velocidade mesmo em evento isolado.',Bsrc,3)
add(B,'Uma empresa investiu em armazenamento, mas não sabe qual decisão quer tomar. O V mais negligenciado é…',['Veracidade','Volume','Velocidade','Valor'],3,'Falta finalidade/benefício para o negócio, aspecto associado ao valor.',Bsrc,2)
add(B,'Uma tabela tem milhões de linhas, incluindo CPFs inconsistentes. O par de características diretamente envolvido é…',['Volume e veracidade','Variedade e velocidade','Velocidade e valor','Veracidade e variedade'],0,'Muitos registros dizem respeito ao volume e inconsistências afetam veracidade.',Bsrc,2)
add(B,'Qual das alternativas é um contraste correto?',['Volume mede confiabilidade e veracidade mede quantidade','Velocidade diz respeito ao tempo e volume à quantidade','Valor é igual a formato de arquivo','Variedade e velocidade sempre crescem juntas'],1,'Volume está ligado ao quanto; velocidade, à rapidez.',Bsrc,1)
add(B,'Ao pedir a um time “demonstre que os dados ajudam a reduzir custos”, qual V está sendo questionado?',['Variedade','Veracidade','Volume','Valor'],3,'Busca-se comprovar o benefício concreto extraído dos dados.',Bsrc,1)
add(B,'Um arquivo mistura XML, planilha e foto. O enunciado destaca variedade porque…',['os registros são necessariamente grandes','há diversidade de representações','o processamento ocorre em microssegundos','houve validação formal da qualidade'],1,'XML, planilha e foto têm estruturas e formatos distintos.',Bsrc,2)
# LOGIC
add(L,'“Todos os contratos assinados digitalmente usam certificado. Este contrato foi assinado digitalmente; logo, usa certificado.” O padrão é…',['Dedutivo','Indutivo','Abdutivo','Crítico'],0,'Regra geral aplicada ao caso específico: dedução.', 'Aula 5 · pp. 3–5 (exemplo didático)',1)
add(L,'Depois de dez falhas ocorrerem nas segundas-feiras, um desenvolvedor supõe que toda segunda haverá falha. Isso é…',['Dedução','Abdução','Indução','Análise'],2,'Generalização de casos observados: indução; a hipótese não é certeza.','Aula 5 · pp. 6–8 (exemplo didático)',1)
add(L,'O servidor parou de responder. O engenheiro suspeita de memória esgotada, sem ainda ter prova. Isso é…',['Crítica','Abdução','Dedução','Indução'],1,'Busca uma explicação plausível para observação com informação incompleta.','Aula 5 · pp. 9–11 (exemplo didático)',1)
add(L,'Para resolver uma falha, a equipe testa rede, aplicação e banco separadamente. Qual raciocínio é central?',['Analítico','Crítico','Indutivo','Dedutivo'],0,'Decompor o problema em partes para compreender o todo é pensamento analítico.','Aula 5 · pp. 12–14 (exemplo didático)',1)
add(L,'Antes de aceitar um relatório, uma gestora questiona fontes, evidências e possíveis vieses. O raciocínio é…',['Dedutivo','Indutivo','Abdutivo','Crítico'],3,'O foco está na avaliação cuidadosa da validade, coerência e evidências.','Aula 5 · pp. 15–17 (exemplo didático)',1)
add(L,'“Vi três cisnes brancos; portanto todos os cisnes são brancos.” Qual risco existe?',['Conclusão dedutivamente garantida','Generalização indevida de amostra limitada','Ausência completa de observações','Decomposição de problema'],1,'Indução gera conclusão provável, sujeita a novas evidências.','Aula 5 · pp. 6–8 (exemplo didático)',2)
add(L,'Rua molhada e nuvens escuras levam à hipótese de chuva. Qual observação torna a hipótese menos segura?',['Existe um aspersor ligado no local','Chuva molha ruas','Há nuvens','A rua está molhada'],0,'Abdução admite explicações alternativas; o aspersor poderia explicar a água.','Aula 5 · pp. 9–11 (exemplo didático)',3)
add(L,'Qual raciocínio parte de uma regra geral e chega a uma conclusão específica, quando a inferência é adequada?',['Crítico','Abdutivo','Dedutivo','Indutivo'],2,'Dedução desce do geral ao caso particular.','Aula 5 · pp. 3–5',1)
add(L,'Qual raciocínio procura uma hipótese que explique uma observação?',['Analítico','Indutivo','Dedutivo','Abdutivo'],3,'Abdução propõe explicação plausível para um fato.','Aula 5 · pp. 9–11',1)
add(L,'Qual alternativa contrasta corretamente indução e dedução?',['Indução generaliza casos; dedução aplica regras gerais','Ambas garantem certeza total','Dedução sempre depende de experimentos','Indução sempre testa uma hipótese causal'],0,'Aula 5 distingue generalização provável de inferência do geral ao específico.',Lsrc,2)
add(L,'O programador cria três hipóteses para um bug e testa a mais provável. A formulação inicial é mais próxima de…',['Dedução','Abdução','Indução obrigatoriamente','Repetição mecânica'],1,'A observação do bug leva à hipótese explicativa plausível.','Aula 5 · pp. 9–11 (exemplo didático)',2)
add(L,'Uma estudante avalia a qualidade das premissas antes de aceitar uma conclusão. A habilidade em foco é…',['Velocidade','Armazenamento','Raciocínio crítico','Modelagem de dados'],2,'Avaliar argumentos e evidências é central ao pensamento crítico.','Aula 5 · pp. 15–17',2)
add(L,'Separar um problema grande em subproblemas NÃO corresponde diretamente a…',['Raciocínio analítico','Decomposição','Organização da resolução','Inferência abdutiva'],3,'Abdução constrói explicações; decomposição caracteriza o analítico.','Aula 5 · pp. 9–14',2)
add(L,'Qual dedução é logicamente sustentada?',['Todos os programadores usam computador; Ana usa computador; então Ana é programadora','Todos os cães são mamíferos; Bob é cão; logo Bob é mamífero','Alguns carros são pretos; logo todos são pretos','A rua está molhada; logo necessariamente choveu'],1,'Uma regra universal aplicada a caso pertencente à classe permite conclusão válida.','Aula 5 · pp. 3–5 (exemplo didático)',3)
add(L,'“Este remédio funcionou em dois pacientes; então funciona em todas as pessoas.” A falha é de…',['Dedução válida','Evidência suficiente','Amostra insuficiente para generalização','Decomposição excessiva'],2,'Uma indução com poucos exemplos não garante uma afirmação universal.','Aula 5 · pp. 6–8 (exemplo didático)',3)
add(L,'Qual estratégia combina pensamento analítico e crítico?',['Aceitar primeiro palpite','Analisar cada componente e avaliar evidências de cada hipótese','Repetir informação sem verificar','Escolher a hipótese mais popular'],1,'É possível decompor um problema e testar a validade de conclusões sobre suas partes.',Lsrc,3)
add(L,'Se você identifica cinco erros diferentes e conclui que todos ocorreram por causa da última atualização, isso é…',['Hipótese explicativa que precisa ser testada','Dedução necessariamente válida','Solução comprovada','Decomposição do sistema'],0,'Atribuir causa provável a observações é uma hipótese abdutiva, não prova.','Aula 5 · pp. 9–11 (exemplo didático)',3)
add(L,'“Todos os A são B. C é A. Portanto, C é B.” É exemplo de…',['Generalização estatística','Hipótese causal','Silogismo dedutivo','Decomposição analítica'],2,'A aula apresenta silogismo com duas premissas e uma conclusão.','Aula 5 · pp. 3–5',1)
add(L,'Qual afirmação sobre conclusão indutiva está correta?',['É sempre matematicamente exata','É impossível na ciência','Dispensa observações','É provável, mas não necessariamente certa'],3,'O PDF destaca caráter provável das conclusões indutivas.','Aula 5 · pp. 6–8',1)
add(L,'Um detetive encontra uma janela quebrada e formula explicações possíveis. Qual raciocínio predomina?',['Indução','Abdução','Dedução','Cálculo algébrico'],1,'Hipóteses explicam um fato observado, mas não são garantidas.','Aula 5 · pp. 9–11 (exemplo didático)',1)
# DATA SCIENCE / AI
add(S,'Uma equipe combina estatística, programação e entendimento do negócio. Isso reproduz qual característica de Data Science?',['Multidisciplinaridade','Apenas visualização','Exclusividade matemática','Ausência de análise'],0,'A Aula 1 lista computação, estatística, matemática e conhecimento do negócio.','Aula 1 · pp. 2–3',1)
add(S,'O profissional formula hipótese, seleciona modelos e avalia resultados. Segundo a Aula 1, aproxima-se mais do papel de…',['Operador de telemarketing','Designer gráfico','Cientista de dados','Analista de suporte'],2,'O material atribui formulação de problemas e modelos ao cientista de dados.','Aula 1 · pp. 4–5',2)
add(S,'Um profissional avalia como números afetam desempenho e decisões da empresa. A ênfase é de…',['Business Analyst','Engenheiro de redes','Administrador de banco apenas','Operador de sistemas'],0,'O perfil Business Analyst é descrito como análise de dados em relação ao negócio.','Aula 1 · pp. 5–7',2)
add(S,'Qual área NÃO está listada entre os pilares multidisciplinares de Data Science na Aula 1?',['Estatística','Computação','Conhecimento do negócio','Arqueologia'],3,'O slide lista computação, estatística, matemática e negócio.','Aula 1 · p. 3',1)
add(A,'Qual enunciado se aproxima mais da definição didática de Inteligência Artificial nos slides?',['Sistemas capazes de executar tarefas que lembram aspectos do raciocínio humano','Qualquer armazenamento em nuvem','Todo software escrito em Python','Todo banco de dados relacional'],0,'O texto relaciona IA à percepção de variáveis, decisões e resolução de problemas.','Aula 1 · pp. 12–14',1)
add(A,'Um programa executa regras previamente definidas para inferir uma conclusão. Qual abordagem dos slides se aproxima disso?',['Abordagem simbólica','Armazenamento mecânico','Captação de dados','Sistema operacional'],0,'A abordagem simbólica é associada a símbolos e regras para representação do conhecimento.','Aula 1 · pp. 31–33',2)
add(A,'Uma rede aprende padrões a partir de exemplos apresentados no treinamento. O conceito está associado a…',['Rede neural artificial','Coleta manual de formulários','Dedução formal obrigatória','Monitoramento contábil'],0,'As redes neurais são apresentadas como estruturas que permitem aprender representações a partir de dados.','Aula 1 · pp. 34–38',2)
add(A,'Qual relação entre IA, ML e Deep Learning é ensinada no material?',['IA é subcampo de Deep Learning','Deep Learning contém toda a IA','Machine Learning e Deep Learning não têm relação','Deep Learning é uma abordagem de ML, que é subárea de IA'],3,'A hierarquia geral é IA ⊃ ML ⊃ Deep Learning.','Aula 1 · pp. 56–62',1)
add(A,'Um sistema recomenda vídeos com base no histórico e ajusta recomendações após interações. Um conceito aplicável é…',['Machine Learning','Somente hardware','Somente sistema operacional','Apenas editor de texto'],0,'A aula menciona recomendação de conteúdo como aplicação de Machine Learning.','Aula 1 · pp. 59–67',1)
add(A,'Uma ferramenta automatiza uma tarefa específica, sem inteligência humana geral. Ela se aproxima da ideia de…',['IA forte em sentido humano','IA fraca/específica','Superinteligência confirmada','Nenhuma forma de IA'],1,'O contraste entre IA forte e fraca aparece nos slides; aplicações específicas não implicam inteligência geral.','Aula 1 · pp. 39–44',2)
add(A,'Ter muitos dados significa automaticamente ter Machine Learning funcionando?',['Sim, dados já são o modelo','Sim, se estiverem em CSV','Não: é preciso um método/modelo de aprendizagem e treinamento','Não: Machine Learning dispensa qualquer dado'],2,'O slide associa ML a alteração de comportamento por experiência/treino, não à mera posse de dados.','Aula 1 · pp. 59–67 (explicação didática)',2)
add(A,'Que alternativa representa uma aplicação de IA citada na Aula 1?',['Previsão e reconhecimento de padrões','Papel sulfite','Armazenamento em gaveta','Apenas digitar números'],0,'Os slides descrevem várias aplicações e capacidades de sistemas inteligentes.','Aula 1 · pp. 45–55',1)
add(A,'Diferencie uma rede neural de um banco SQL tradicional. Qual afirmação é adequada?',['SQL sempre aprende padrões sozinho','Rede neural pode aprender parâmetros no treinamento; banco SQL organiza/consulta dados','Banco SQL é sempre IA forte','Nenhuma rede neural usa matemática'],1,'Redes neurais e sistemas tradicionais de dados cumprem funções diferentes.','Aula 1 · pp. 34–38 (comparação didática)',3)
add(A,'A IA conexionista é mais diretamente associada no material a…',['Tabelas contábeis','Regras escritas em linguagem natural','Redes neurais e conexões entre unidades','Cabos de rede físicos'],2,'O material distingue simbolismo de modelos conexionistas.','Aula 1 · pp. 31–38',2)
add(A,'Qual interpretação sobre “IA forte” exige cautela?',['É conceito tratado nos slides','Pode ser usada em contraste com IA fraca','Os exemplos de IA atual não demonstram necessariamente inteligência geral','Qualquer chatbot prova a existência de IA forte'],3,'Aplicação de IA não demonstra por si só inteligência geral; a categoria forte tem interpretação própria.','Aula 1 · pp. 39–44 (nota conceitual)',3)
add(A,'Uma plataforma aprende a identificar fraudes a partir de histórico de transações. O caso ilustra…',['Um processo de Machine Learning','Um tipo obrigatório de Power BI','Um raciocínio dedutivo puro sem treinamento','Um dado não estruturado necessariamente'],0,'Aprender padrões com exemplos é um cenário típico de ML citado na aula.','Aula 1 · pp. 59–67 (exemplo didático)',2)
# BI
add(I,'Um painel organiza dados de vendas e ajuda o gestor a decidir onde investir. O processo exemplifica…',['IA forte','Business Intelligence','Apenas tráfego de rede','Somente UX'],1,'BI organiza e interpreta dados para auxiliar decisões de negócio.','Aula 1 · pp. 68–72 (exemplo didático)',1)
add(I,'Qual das alternativas distingue BI de Power BI?',['BI é conceito/processo; Power BI é uma ferramenta possível','São exatamente a mesma coisa','Power BI é toda ciência de dados','BI dispensa dados'],0,'O estudo de BI não depende de dominar uma ferramenta específica.','Aula 1 · pp. 68–85 (explicação didática)',2)
add(I,'Em BI, a equipe define uma meta estratégica antes de escolher indicadores. Qual pilar predomina?',['Operacional','Analítico','Estratégico','Infraestrutura'],2,'O pilar estratégico é responsável por direção, metas e planejamento.','Aula 1 · pp. 73–76',2)
add(I,'Uma equipe investiga quais produtos mais sofreram devoluções. O pilar mais relacionado é…',['Operacional','Analítico','Estratégico','Jurídico'],1,'O foco é interpretar dados para compreender a situação.','Aula 1 · pp. 73–76 (exemplo didático)',2)
add(I,'Após analisar os resultados, a empresa muda sua rotina de reposição. Qual pilar está em ação?',['Estratégico','Analítico','Operacional','Estatístico'],2,'A implementação operacional aplica decisões e estratégias.','Aula 1 · pp. 73–76 (exemplo didático)',2)
add(I,'Após aplicar um plano de BI, a empresa mede se a conversão melhorou. Essa etapa corresponde a…',['Acompanhamento de performance','Descarte de informações','Coleta inicial exclusivamente','Apenas hardware'],0,'O acompanhamento verifica os efeitos das ações executadas.','Aula 1 · pp. 77–85',1)
add(I,'Qual sequência melhor resume o fluxo apresentado no material?',['Agir sem informação → coletar → esquecer','Coletar → analisar → gerar insights/estratégias → acompanhar','Acompanhar → apagar → construir telas','Treinar IA → excluir clientes → encerrar'],1,'O slide organiza o ciclo desde coleta e análise até resultados e monitoramento.','Aula 1 · pp. 77–85',1)
add(I,'BI substitui inteiramente a responsabilidade humana por decisões empresariais?',['Sim, sempre','Sim, quando houver dashboards','Não, fornece informação para apoiar a tomada de decisão','Sim, quando há muitos gráficos'],2,'Os slides enfatizam apoio e inteligência para escolhas, não decisão automática universal.','Aula 1 · pp. 68–72',3)
