add(C,'Um site registra origem das visitas para avaliar uma campanha. Qual atividade começa esse processo?',['Coleta de dados','Tomada de decisão sem evidência','Treino de hardware','Dedução obrigatória'],0,'Capturar interações e eventos é parte da coleta.','Aula 2 · pp. 2–17 (exemplo didático)',1)
add(C,'Uma empresa decide coletar todos os dados possíveis sem objetivo claro. Que orientação da Aula 2 ela ignora?',['Uso de fonte confiável apenas','Definição de objetivos e planejamento','Compra de sensores obrigatória','Publicidade tradicional'],1,'Os slides orientam estabelecer objetivos e planejar a coleta.','Aula 2 · pp. 29–39',2)
add(C,'Qual indicador citado no material é útil para acompanhar o desempenho comercial?',['Número de janelas abertas','Cor do menu','Ticket médio','Tipo de cabo'],2,'Ticket médio aparece como exemplo de KPI na Aula 2.','Aula 2 · pp. 18–22',1)
add(C,'Uma loja pesquisa a satisfação de quem acabou de comprar. Qual meio de coleta é mais direto?',['Formulário de feedback','Compilador de código','Monitoramento de voltagem','Editor de planilhas vazio'],0,'Formulários são apresentados como instrumentos úteis para respostas de consumidores.','Aula 2 · pp. 40–45 (exemplo didático)',1)
add(C,'Por que dados de clique isolados podem não ser suficientes para concluir que clientes estão satisfeitos?',['Porque cliques são sempre falsos','Porque análise exige contexto e indicadores apropriados','Porque satisfação é igual a velocidade','Porque todo clique já é venda'],1,'Dados precisam ser interpretados de acordo com objetivos e demais evidências.','Aula 2 · pp. 20–39 (explicação didática)',3)
add(C,'Um sistema registra abandonos no checkout e a equipe mede o efeito de uma alteração no fluxo. Isso ilustra…',['Processo cíclico de coleta, análise e melhoria','Somente captura sem consequência','IA forte necessariamente','Ausência de indicadores'],0,'A coleta alimenta a análise e pode orientar ajustes de estratégia.','Aula 2 · pp. 2–39 (exemplo didático)',2)
add(C,'Qual ferramenta citada nos slides está associada a mensuração de tráfego e comportamento digital?',['Google Analytics','Editor de áudio','IDE de programação','Cliente FTP'],0,'A Aula 2 inclui Google Analytics como ferramenta relacionada à coleta digital.','Aula 2 · pp. 40–45',2)
add(C,'Uma campanha atraiu muitas visitas, mas gerou poucas compras. O próximo passo coerente é…',['Desprezar as métricas','Analisar conversão e possíveis gargalos','Aumentar todo orçamento sem análise','Eliminar toda coleta'],1,'Coletar dados só é útil quando eles são analisados para orientar decisões.','Aula 2 · pp. 20–39 (exemplo didático)',2)
add(C,'Qual alternativa melhor distingue métrica de KPI?',['Toda métrica tem relevância estratégica','KPI é métrica selecionada por sua relação com um objetivo relevante','KPI nunca pode ser numérico','Métrica não mede nada'],1,'KPIs são indicadores-chave associados a metas; nem toda métrica tem esse papel.','Aula 2 · pp. 18–22 (explicação didática)',3)
add(C,'Uma empresa quer saber por que clientes cancelam o serviço. Qual primeira decisão é mais adequada?',['Definir a questão e fontes de dados relevantes','Adquirir hardware ao acaso','Excluir entrevistas','Assumir que todos cancelam pelo preço'],0,'Planejamento da coleta começa por objetivos e perguntas a responder.','Aula 2 · pp. 29–39',2)
