add(E,'O que caracteriza melhor ética de dados na Aula 3?',['Só impedir acesso por senha','Considerar implicações morais em toda a cadeia de uso de dados','Apenas armazenar dados mais rápido','Abrir todos os dados sem restrições'],1,'A ética aborda impactos e responsabilidades em todas as etapas, além da privacidade.','Aula 3 · pp. 6–9',1)
add(E,'Coletar dados apenas porque é tecnicamente possível é necessariamente ético?',['Sim, tecnologia autoriza uso','Sim, se o arquivo for grande','Não: impactos, finalidade e responsabilidades precisam ser considerados','Sim, se o modelo usa IA'],2,'Possibilidade técnica não substitui reflexão ética e obrigações legais.','Aula 3 · pp. 6–16 (explicação didática)',2)
add(E,'Um modelo favorece injustamente um grupo por padrão enviesado. O problema está ligado a…',['Discriminação algorítmica','Velocidade de rede','Variedade de arquivos','Tamanho do banco'],0,'A parte final da Aula 3 discute danos e riscos no uso de dados e algoritmos.','Aula 3 · pp. 26–31',2)
add(E,'Uma organização divulga registros pessoais sem precauções adequadas. O risco se relaciona a…',['Apenas visualização','Um aumento automático de valor','Privacidade e segurança dos dados','Um tipo de dedução'],2,'Proteção e uso responsável de informações são temas da Aula 3.','Aula 3 · pp. 2–31',1)
