for lesson in db['lessons']:
    src=f"{lesson['src']} · p. {lesson['pages']}"
    db['cards'].append({'id':f'v2fc-{lesson["id"]}', 'module':lesson['module'], 'front':f'Qual a pegadinha em “{lesson["title"]}”?', 'back':lesson['trap'][:220], 'source':src})
    db['cards'].append({'id':f'v2fm-{lesson["id"]}', 'module':lesson['module'], 'front':f'Como lembrar “{lesson["title"]}”?', 'back':lesson['mnemonic'][:220], 'source':src})
# Situational missions for contextual learning, with explicit source note
scenarios=[]
def scenario(title,story,choices,correct,why,module,source):
    scenarios.append(dict(id=f'c{len(scenarios)+1:02}',title=title,story=story,choices=choices,correct=correct,explain=why,module=module,source=source))
vs=['Volume','Velocidade','Variedade','Veracidade','Valor']
scenario('Marketplace de eventos','O marketplace recebe 50 milhões de novos eventos por hora, mas o enunciado pergunta principalmente pela quantidade total processada.',vs,0,'Quantidade de dados é Volume, ainda que eventos possam também chegar rapidamente.',B,Bsrc)
scenario('Radar de trânsito','Para frear um veículo, o radar deve enviar resposta em poucos milissegundos.',vs,1,'O desafio é o tempo de resposta: Velocidade.',B,Bsrc)
scenario('Central de arquivos','Uma central recebe vídeos, documentos PDF, mensagens e eventos JSON.',vs,2,'Múltiplos formatos e estruturas refletem Variedade.',B,Bsrc)
scenario('Cadastro suspeito','Uma universidade detecta números impossíveis em históricos de alunos.',vs,3,'Campos inconsistentes prejudicam Veracidade.',B,Bsrc)
scenario('Melhorar entrega','Uma transportadora analisa dados e reduz atrasos de forma mensurável.',vs,4,'O benefício realizado representa Valor.',B,Bsrc)
scenario('Sensores quebrados','Um sensor envia leituras rapidamente, mas mede temperatura errada. Qual dimensão requer correção?',vs,3,'Há um problema de confiabilidade dos dados.',B,Bsrc)
scenario('Visitas em tempo real','O dashboard precisa se atualizar em menos de um segundo a cada visita.',vs,1,'A ênfase está na rapidez da entrada/tratamento.',B,Bsrc)
scenario('Milhões de imagens','O museu armazena milhões de fotos em JPEG. O foco está no tamanho do conjunto.',vs,0,'O formato é único, e o desafio descrito é quantidade.',B,Bsrc)
scenario('Informação que gera receita','Ao personalizar ofertas usando dados, a empresa aumenta receita com efeito comprovado.',vs,4,'A aplicação útil dos dados revela Valor.',B,Bsrc)
scenario('Bases heterogêneas','Um pesquisador reúne planilhas, imagens de microscopia e áudios clínicos.',vs,2,'Tipos diferentes de dados evidenciam Variedade.',B,Bsrc)
logic=['Dedutivo','Indutivo','Abdutivo','Analítico','Crítico']
scenario('API instável','O técnico divide o diagnóstico em logs, autenticação, cache e banco.',logic,3,'Decomposição em partes descreve raciocínio Analítico.',L,Lsrc)
scenario('Lentidão na segunda','A equipe nota quatro segundas com lentidão e suspeita que toda segunda será assim.',logic,1,'Generalização de observações é Indutivo; não garante certeza.',L,Lsrc)
scenario('Fumaça na sala','Ao ver fumaça, a equipe considera um curto-circuito como hipótese explicativa.',logic,2,'Busca da explicação plausível é Abdutivo.',L,Lsrc)
scenario('Premissas e regras','Todos os pedidos confirmados foram faturados. O pedido 102 foi confirmado. Logo ele foi faturado.',logic,0,'Regra geral aplicada a caso: Dedutivo.',L,Lsrc)
scenario('Relatório duvidoso','O gestor questiona fonte, validade da amostra e coerência do argumento.',logic,4,'Avaliação das evidências: Crítico.',L,Lsrc)
scenario('Debug por módulos','O erro parece enorme; você isola cada componente e testa separadamente.',logic,3,'Quebrar problema em partes é Analítico.',L,Lsrc)
scenario('Suposição de gripe','Febre e tosse levam à hipótese de gripe, mas outras causas são possíveis.',logic,2,'Hipótese explicativa a partir de sintomas: Abdutivo.',L,Lsrc)
scenario('Todos os mamíferos','Todos os mamíferos respiram. Golfinho é mamífero. Logo respira.',logic,0,'Forma de silogismo: Dedutivo.',L,Lsrc)
scenario('Analisando notícia','Antes de compartilhar, alguém verifica autor, evidência e alternativas.',logic,4,'Exame reflexivo do argumento: Crítico.',L,Lsrc)
scenario('Últimas entregas','Nove pedidos seguidos atrasaram. A equipe prevê que todos atrasarão.',logic,1,'Generalização provável e sujeita a erro: Indutivo.',L,Lsrc)
db['scenarios']=scenarios
